def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]

    # Find solid, same-color rectangles of at least 4x4.
    for top in range(h - 3):
        for bottom in range(top + 3, h):
            start = None
            color = None
            for c in range(w + 1):
                current = None
                if c < w:
                    v = grid[top][c]
                    if all(grid[r][c] == v for r in range(top + 1, bottom + 1)):
                        current = v

                if current == color and current is not None:
                    continue

                if start is not None and c - start >= 4:
                    for r in range(top, bottom + 1):
                        for x in range(start, c):
                            marked[r][x] = True

                if current is None:
                    start = None
                    color = None
                else:
                    start = c
                    color = current

    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
